def _load(path):
    return json.loads(path.read_text(encoding="utf-8"))


def _digest(payload):
    return hashlib.sha256(payload).hexdigest()


def _case_digest(case):
    return _digest(
        json.dumps(
            case, ensure_ascii=False, sort_keys=True, separators=(",", ":"), allow_nan=False
        ).encode("utf-8")
    )


def _assert_publication_wrapper(published, language):
    text = published.decode("utf-8")
    tables = re.findall(r"\\begin\{table\*\}\[t\](.*?)\\end\{table\*\}", text, re.DOTALL)
    assert len(tables) == 3, "All three audit tables must occupy the full two-column width"
    assert text.count(r"\begin{tabular}") == 3
    assert re.findall(r"\\label\{([^{}]+)\}", text) == list(AUDIT_TABLE_LABELS)
    for table, label in zip(tables, AUDIT_TABLE_LABELS):
        assert table.count(r"\begin{tabular}") == table.count(r"\end{tabular}") == 1
        assert table.count(r"\caption{") == 1
        assert re.findall(r"\\label\{([^{}]+)\}", table) == [label]

    # Undo only approved typography substitutions/insertions within each table.
    # Separate typography tests require the treatment; no numeric or prose bytes
    # are normalized here, and unexpected extra commands survive to fail equality.
    restored = published
    for index, table in enumerate(tables):
        original = table.encode("utf-8")
        unstyled = original.replace(b"\\renewcommand{\\arraystretch}{1.20}\n", b"", 1)
        for rule in (b"\\toprule\n", b"\\midrule\n", b"\\bottomrule\n"):
            unstyled = unstyled.replace(rule, b"\\hline\n" if index < 2 else b"", 1)
        restored = restored.replace(original, unstyled, 1)

    # Strip only the explicitly approved publication wrapper and labels. Every
    # original byte, including all numbers, prose and whitespace, must survive.
    for label in AUDIT_TABLE_LABELS[:2]:
        insertion = f"\\label{{{label}}}\n".encode()
        assert restored.count(insertion) == 1
        restored = restored.replace(insertion, b"", 1)
    tabular_start = b"\\begin{tabular}{lrrrr}\n"
    opening = b"\\begin{table*}[t]\n\\centering\n\\scriptsize\n"
    assert restored.count(opening + tabular_start) == 1
    restored = restored.replace(opening + tabular_start, tabular_start, 1)
    tabular_end = b"\\end{tabular}\n"
    closing = (
        f"\\caption{{{SURFACE_CAPTIONS[language]}}}\n"
        "\\label{tab:review-surface-sentinels}\n\\end{table*}\n"
    ).encode()
    assert restored.count(tabular_end + closing) == 1
    restored = restored.replace(tabular_end + closing, tabular_end, 1)
    assert restored == (FROZEN / f"review_boundary_audit_{language}.tex").read_bytes()


def _assert_strict_reviewer_source_bytes(root):
    """Check original bytes only when both genuine local copies are available."""
    canonical, frozen = (
        (root / AUDIT / relative).read_bytes() for relative in WITHHELD_REVIEWER_SOURCES
    )
    assert _digest(canonical) == ORIGINAL_REVIEWER_SOURCE_SHA256
    assert _digest(frozen) == ORIGINAL_REVIEWER_SOURCE_SHA256
    assert len(canonical) == len(frozen) == 20336
    assert frozen == canonical


@pytest.fixture(scope="module")
def public_packet_root(tmp_path_factory):
    """Copy genuine packet/source bytes once, then withhold only two originals."""
    project = tmp_path_factory.mktemp("PUBLIC-review-packet") / ROOT.name
    shutil.copytree(ROOT / AUDIT, project / AUDIT)
    shutil.copytree(ROOT / "src/nesy_game", project / "src/nesy_game")
    (project / "scripts").mkdir()
    for name in ("run_gemini_review_evaluation.py", "review_reference.py"):
        shutil.copyfile(ROOT / "scripts" / name, project / "scripts" / name)
    originals = [project / AUDIT / relative for relative in WITHHELD_REVIEWER_SOURCES]
    if all(path.is_file() for path in originals):
        _assert_strict_reviewer_source_bytes(project)
    # Public CI need not contain either private original. No source is rebuilt
    # from the derivative, and this fixture never reads a private archive.
    for path in originals:
        path.unlink(missing_ok=True)
        assert not path.exists()
    return project


