def test_public_packet_pins_original_commitments_without_claiming_private_reverification(packet):
    audit = packet["root"] / AUDIT
    receipt_bytes = (audit / "public-source-projection-v1.json").read_bytes()
    assert len(receipt_bytes) == 2618
    assert _digest(receipt_bytes) == PUBLIC_PROJECTION_SHA256
    receipt = json.loads(receipt_bytes)
    assert receipt["schema_version"] == "public-source-projection-v1"
    assert receipt["artifact_classification"] == "publication-derivative"
    assert receipt["projection"]["allowed_semantic_operations"] == [
        {"op": "remove", "path": "/url"}
    ]
    assert receipt["projection"]["all_other_json_fields"] == "UNCHANGED"
    assert receipt["original_commitments"] == {
        "input_manifest": {
            "path": "results-v2/input_hashes.json",
            "sha256": INPUT_MANIFEST_SHA256,
            "bytes": 649,
        },
        "source_manifest": {
            "path": "results-v2/source_hashes.json",
            "sha256": SOURCE_MANIFEST_SHA256,
            "bytes": 2204,
        },
    }
    for identity in receipt["original_commitments"].values():
        payload = (audit / identity["path"]).read_bytes()
        assert len(payload) == identity["bytes"]
        assert _digest(payload) == identity["sha256"]
    assert receipt["public_derivative"] == {
        "path": "reviewer-source.public.json",
        "sha256": PUBLIC_REVIEWER_SOURCE_SHA256,
        "bytes": 20262,
    }
    assert receipt["mappings"] == [
        {
            "original": {
                "path": relative,
                "sha256": ORIGINAL_REVIEWER_SOURCE_SHA256,
                "bytes": 20336,
            },
            "public_path": "reviewer-source.public.json",
        }
        for relative in WITHHELD_REVIEWER_SOURCES
    ]
    for relative in WITHHELD_REVIEWER_SOURCES:
        assert not (audit / relative).exists()
    public_source = (audit / "reviewer-source.public.json").read_bytes()
    assert len(public_source) == 20262
    assert _digest(public_source) == PUBLIC_REVIEWER_SOURCE_SHA256
    assert "url" not in json.loads(public_source)
    assert receipt["verification_scope"]["private_original_archive_reverification"] == (
        "NOT_PERFORMED_BY_PUBLIC_COMMAND"
    )
    # The pinned receipt is a public commitment, not byte/semantic equality
    # evidence for the two withheld originals; only the strict helper checks those.


def test_frozen_digests_bind_exact_inputs_and_executed_sources(packet):
    """PUBLIC contract: hash all retained bytes; preserve withheld commitments."""
    root, frozen = packet["root"], packet["frozen"]
    assert _digest((frozen / "input_hashes.json").read_bytes()) == INPUT_MANIFEST_SHA256
    assert _digest((frozen / "source_hashes.json").read_bytes()) == SOURCE_MANIFEST_SHA256
    for name, digest in OUTCOME_SHA256.items():
        assert _digest((frozen / name).read_bytes()) == digest, name
    input_hashes = _load(frozen / "input_hashes.json")
    assert set(input_hashes) == {
        "protocol.json",
        "cases.json",
        "surface_sentinels.json",
        "assignment_inventory.json",
        "source_hashes.json",
        "reviewer-source.json",
        "review-response.json",
    }
    for name, digest in input_hashes.items():
        if name == "reviewer-source.json":
            assert digest == ORIGINAL_REVIEWER_SOURCE_SHA256
            assert not (frozen / name).exists()
        else:
            assert _digest((frozen / name).read_bytes()) == digest, name
    sources = _load(frozen / "source_hashes.json")
    required = {
        str(AUDIT / name)
        for name in ("protocol-v2.json", "reviewer-source.json", "review-response.json")
    } | {"scripts/run_gemini_review_evaluation.py", "scripts/review_reference.py"}
    required.update(str(path.relative_to(root)) for path in (root / "src/nesy_game").glob("*.py"))
    assert set(sources) == required
    assert sources["scripts/run_gemini_review_evaluation.py"] == EXECUTED_RUNNER_SHA256
    for name, digest in sources.items():
        if name == str(AUDIT / "reviewer-source.json"):
            assert digest == ORIGINAL_REVIEWER_SOURCE_SHA256
            assert not (root / name).exists()
        else:
            assert _digest((root / name).read_bytes()) == digest, name
    for frozen_name, canonical_name in (
        ("protocol.json", "protocol-v2.json"),
        ("review-response.json", "review-response.json"),
    ):
        assert (frozen / frozen_name).read_bytes() == (root / AUDIT / canonical_name).read_bytes()
    assert packet["summary"]["input_hashes"] == input_hashes
    assert packet["summary"]["source_hashes"] == sources
    for rows in packet["rows"].values():
        for row in rows:
            assert row["source_hashes"] == sources, (row["case_id"], row["arm"])


def test_every_frozen_assignment_has_exactly_one_unpooled_raw_outcome(packet):
    protocol = packet["protocol"]
    assert tuple(arm["id"] for arm in protocol["arms"]) == ARMS
    expected = Counter(
        (cohort, case["case_id"], arm)
        for cohort, cases in packet["inputs"].items()
        for case in cases
        for arm in ARMS
    )
    inventory = Counter((row["cohort"], row["case_id"], row["arm"]) for row in packet["inventory"])
    assert inventory == expected
    assert set(inventory.values()) == {1}
    assert len(packet["inputs"]["core"]) == protocol["assignment_count_per_arm"] == 416
    assert len(packet["inputs"]["surface"]) == protocol["surface_sentinels"]["units_per_arm"] == 12
    case_ids = {
        cohort: {case["case_id"] for case in cases} for cohort, cases in packet["inputs"].items()
    }
    assert case_ids["core"].isdisjoint(case_ids["surface"])
    actual = Counter()
    for cohort, rows in packet["rows"].items():
        inputs = {case["case_id"]: case for case in packet["inputs"][cohort]}
        assert len(inputs) == len(packet["inputs"][cohort])
        for row in rows:
            assert row["cohort"] == cohort
            actual[(cohort, row["case_id"], row["arm"])] += 1
            case = inputs[row["case_id"]]
            assert row["input_hash"] == _case_digest(case)
            assert row["initial_state"] == case["state"]
            assert row["initial_candidate"] == case["candidate"]
            assert row["status"] in {"COMMITTED", "HOLD", "FAILED"}
            assert (row["error"] is not None) == (row["status"] == "FAILED")
    assert actual == expected
    assert Counter(key[0] for key in actual) == Counter(core=1664, surface=48)


@pytest.mark.parametrize("cohort,stem", (("core", "rows"), ("surface", "surface_rows")))
def test_csv_exports_retain_every_jsonl_outcome_and_measurement(packet, cohort, stem):
    with (packet["frozen"] / f"{stem}.csv").open(encoding="utf-8", newline="") as handle:
        exported = list(csv.DictReader(handle))
    expected = []
    for row in packet["rows"][cohort]:
        expected.append(
            {
                key: (
                    json.dumps(value, ensure_ascii=False, sort_keys=True, separators=(",", ":"))
                    if isinstance(value, (dict, list))
                    else ""
                    if value is None
                    else str(value)
                )
                for key, value in row.items()
            }
        )
    # Compare complete records, including failed status/error and measured latency, not just IDs.
    assert exported == expected


@pytest.mark.parametrize("cohort", ("core", "surface"))
@pytest.mark.parametrize("arm", ARMS)
def test_summary_counts_and_distinct_denominators_match_all_raw_rows(packet, cohort, arm):
    rows = [row for row in packet["rows"][cohort] if row["arm"] == arm]
    counts = packet["summary"][cohort][arm]
    outcomes = Counter(row["status"] for row in rows)
    valid = [row for row in rows if row["reference_initial_valid"] is True]
    invalid = [row for row in rows if row["reference_initial_valid"] is False]
    commits = [row for row in rows if row["status"] == "COMMITTED"]
    safe = [row for row in commits if row["reference_final_valid"] is True]
    recovered = [row for row in safe if row["reference_initial_valid"] is False]
    retained = [
        row
        for row in safe
        if row["reference_initial_valid"] is True
        and row["initial_signature"] == row["final_signature"]
    ]
    assert counts["assigned"] == len(rows) == sum(outcomes.values())
    for metric, status in (("committed", "COMMITTED"), ("held", "HOLD"), ("failed", "FAILED")):
        assert counts[metric] == outcomes[status]
    assert counts["assigned"] == counts["committed"] + counts["held"] + counts["failed"]
    assert counts["initial_valid"] == len(valid)
    assert counts["initial_invalid"] == len(invalid)
    assert counts["initial_reference_evaluated"] == len(valid) + len(invalid)
    assert counts["initial_reference_unknown"] == len(rows) - len(valid) - len(invalid) == 0
    assert counts["safe_commits"] == len(safe)
    assert counts["unsafe_commits"] == sum(row["reference_final_valid"] is False for row in commits)
    assert (
        counts["commit_reference_unknown"]
        == sum(row["reference_final_valid"] is None for row in commits)
        == 0
    )
    assert counts["repair_successes"] == len(recovered)
    assert counts["false_rejections"] == sum(row["status"] == "HOLD" for row in valid)
    assert counts["goals"] == sum(row["goal_reached"] is True for row in commits)
    initial_signatures = {row["initial_signature"] for row in valid}
    retained_signatures = {row["initial_signature"] for row in retained}
    assert counts["valid_initial_signature_count"] == len(initial_signatures)
    assert counts["valid_retained_signature_count"] == len(retained_signatures)
    assert counts["valid_signature_preserved"] == len(retained)
    assert counts["invalid_initial_signature_count"] == len(
        {row["initial_signature"] for row in invalid}
    )
    assert counts["repaired_signature_count"] == len({row["final_signature"] for row in recovered})
    for numerator, denominator, rate, expected_denominator in (
        ("initial_invalid", "pre_gate_invalid_denominator", "pre_gate_invalid_rate", len(rows)),
        ("repair_successes", "repair_success_denominator", "repair_success_rate", len(invalid)),
        ("held", "terminal_hold_denominator", "terminal_hold_rate", len(rows)),
        ("unsafe_commits", "unsafe_commit_denominator", "unsafe_commit_rate", len(rows)),
        (
            "unsafe_commits",
            "unsafe_commit_among_commits_denominator",
            "unsafe_commit_among_commits_rate",
            len(commits),
        ),
        ("false_rejections", "false_rejection_denominator", "false_rejection_rate", len(valid)),
        ("goals", "goal_denominator", "goal_rate", len(rows)),
        (
            "valid_retained_signature_count",
            "valid_signature_denominator",
            "valid_signature_retention_rate",
            len(initial_signatures),
        ),
    ):
        assert counts[denominator] == expected_denominator
        assert counts[rate] == pytest.approx(counts[numerator] / expected_denominator)
    assert counts["valid_signature_case_denominator"] == len(valid)
    assert counts["repair_attempts_executed"] == sum(row["repair_attempt_count"] for row in rows)
    assert counts["native_replay_emitted"] == sum(
        row["native_replay_equal"] is not None for row in rows
    )
    assert counts["native_replay_equal"] == sum(row["native_replay_equal"] is True for row in rows)
    assert counts["latency_ms_total"] == pytest.approx(sum(row["latency_ms"] for row in rows))
    assert counts["latency_ms_mean"] == pytest.approx(counts["latency_ms_total"] / len(rows))


def test_observed_audit_is_offline_and_surface_pairs_keep_their_own_denominators(packet):
    for record in [packet["summary"], *packet["rows"]["core"], *packet["rows"]["surface"]]:
        assert record["model_called"] is False
        assert record["model_id"] is None
        assert record["model_revision"] is None
        assert record["cost_usd"] is None
    for arm in ARMS:
        rows = [row for row in packet["rows"]["surface"] if row["arm"] == arm]
        pairs = packet["summary"]["surface_pairs"][arm]
        assert Counter(row["variant"] for row in rows) == Counter(
            surface_declared=6, surface_undeclared=6
        )
        for variant, prefix, status in (
            ("surface_declared", "declared", "HOLD"),
            ("surface_undeclared", "undeclared", "COMMITTED"),
        ):
            selected = [row for row in rows if row["variant"] == variant]
            assert pairs[f"{prefix}_assigned"] == len(selected) == 6
            metric = "held" if status == "HOLD" else "committed"
            assert pairs[f"{prefix}_{metric}"] == sum(row["status"] == status for row in selected)
        assert pairs["narrative_state_mutation_checks"] == len(rows) == 12
        for row in rows:
            effects = row["final_candidate"]["effects"] if row["status"] == "COMMITTED" else []
            assert set(row["final_state"]["facts"]) == set(row["initial_state"]["facts"]) | set(
                effects
            )
            assert row["final_state"]["quest_stage"] == row["initial_state"]["quest_stage"]
        assert pairs["narrative_state_mutation_mismatches"] == []


def test_graph_agreement_has_one_witness_per_frozen_graph_state(packet):
    states = packet["summary"]["graph_agreement"]
    witnesses = {row["state_id"]: row for row in states["states"]}
    state_ids = {case["state"]["state_id"] for case in packet["inputs"]["core"]}
    assert len(witnesses) == len(states["states"]) == len(state_ids) == 32
    assert set(witnesses) == state_ids
    assert states["assigned"] == len(state_ids)
    assert states["agreements"] == sum(row["closure"] == row["bfs"] for row in witnesses.values())
    assert states["mismatches"] == []
    for row in packet["rows"]["core"]:
        witness = witnesses[row["initial_state"]["state_id"]]
        assert row["production_reachable_locations"] == witness["closure"]
        assert row["reference_reachable_locations"] == witness["bfs"]
        assert row["graph_agreement"] is witness["agrees"] is True


@pytest.mark.parametrize("language", LANGUAGES)
def test_bilingual_numeric_tables_publish_distinct_raw_count_denominators(packet, language):
    text = (packet["frozen"] / f"review_boundary_audit_{language}.tex").read_text(encoding="utf-8")
    tables = re.findall(r"\\begin\{tabular\}\{[^{}]+\}(.*?)\\end\{tabular\}", text, re.DOTALL)
    assert len(tables) == 3
    actual = []
    for table in tables:
        rows = {}
        for line in table.splitlines():
            cells = [cell.strip() for cell in line.removesuffix(r"\\").split("&")]
            arm = cells[0].replace(r"\_", "_")
            if arm in ARMS:
                assert arm not in rows
                rows[arm] = cells[1:]
        actual.append(rows)
    for arm in ARMS:
        core = packet["summary"]["core"][arm]
        surface = packet["summary"]["surface"][arm]
        pairs = packet["summary"]["surface_pairs"][arm]
        assert actual[0][arm] == [
            str(core["assigned"]),
            *[
                f"{core[numerator]}/{core[denominator]}"
                for numerator, denominator in (
                    ("initial_invalid", "pre_gate_invalid_denominator"),
                    ("repair_successes", "repair_success_denominator"),
                    ("held", "terminal_hold_denominator"),
                    ("unsafe_commits", "unsafe_commit_denominator"),
                    ("false_rejections", "false_rejection_denominator"),
                    ("goals", "goal_denominator"),
                )
            ],
            str(core["failed"]),
        ]
        assert actual[1][arm] == [
            f"{core['valid_retained_signature_count']}/{core['valid_signature_denominator']}",
            f"{core['valid_signature_preserved']}/{core['valid_signature_case_denominator']}",
            str(core["invalid_initial_signature_count"]),
            str(core["repaired_signature_count"]),
            f"{core['unsafe_commits']}/{core['unsafe_commit_among_commits_denominator']}",
        ]
        assert actual[2][arm] == [
            str(surface["assigned"]),
            f"{pairs['undeclared_committed']}/{pairs['undeclared_assigned']}",
            f"{pairs['declared_held']}/{pairs['declared_assigned']}",
            str(surface["failed"]),
        ]
    assert all(set(rows) == set(ARMS) for rows in actual)


@pytest.mark.parametrize("language", LANGUAGES)
def test_manuscript_consumes_its_exact_canonical_observed_fragment(language):
    name = f"review_boundary_audit_{language}.tex"
    # These are published data and TeX dependency declarations, not implementation spelling.
    text = (ROOT / "paper/latex" / language / "main.tex").read_text(encoding="utf-8")
    text = re.sub(r"(?<!\\)%[^\n]*", "", text)
    audit_inputs = [
        item
        for item in re.findall(r"\\input\s*\{([^{}]+)\}", text)
        if "review_boundary_audit_" in item
    ]
    assert audit_inputs == [f"../generated/{name}"]
    _assert_publication_wrapper((GENERATED / name).read_bytes(), language)


def test_existing_publication_cli_reproduces_frozen_fragments_without_experiment(tmp_path):
    # Only frozen publication inputs exist in this isolated repository: no runner,
    # production modules, cases, or raw outcomes are available to execute an audit.
    paths = [
        Path("scripts/generate_paper_results.py"),
        Path("research/academic-pipeline/stage-04-pilot/pilot-results.json"),
        Path("research/academic-pipeline/contribution-evidence-matrix.csv"),
        Path("research/academic-pipeline/experiment-evidence-matrix.csv"),
        *(AUDIT / "results-v2" / f"review_boundary_audit_{language}.tex" for language in LANGUAGES),
    ]
    for relative in paths:
        destination = tmp_path / relative
        destination.parent.mkdir(parents=True, exist_ok=True)
        shutil.copyfile(ROOT / relative, destination)
    frozen_before = {relative: (tmp_path / relative).read_bytes() for relative in paths[1:]}
    result = subprocess.run(
        [sys.executable, str(tmp_path / paths[0])],
        cwd=tmp_path,
        capture_output=True,
        text=True,
        check=False,
    )
    assert result.returncode == 0, result.stdout + result.stderr
    for language in LANGUAGES:
        name = f"review_boundary_audit_{language}.tex"
        _assert_publication_wrapper(
            (tmp_path / "paper/latex/generated" / name).read_bytes(), language
        )
    assert {relative: (tmp_path / relative).read_bytes() for relative in paths[1:]} == frozen_before


@pytest.mark.parametrize("language", LANGUAGES)
@pytest.mark.parametrize("preceding_tables", (2, 16, 37))
def test_identity_publication_table_continues_surrounding_numbering(language, preceding_tables):
    from scripts import generate_runtime_comparison_publication as publication

    fragment = publication.render_identity_fragment(
        publication.load_identity_results(), korean=language == "ko"
    )
    # Evaluate the table-counter operations in the emitted TeX artifact, not the
    # generator's source. Varying the incoming counter catches any hardcoded reset.
    tokens = re.finditer(
        r"\\(?:(setcounter|addtocounter)\{table\}\{(-?\d+)\}|(caption)\{|label\{([^{}]+)\})",
        fragment,
    )
    counter = preceding_tables
    labels = {}
    captions = 0
    for token in tokens:
        operation, value, caption, label = token.groups()
        if operation == "setcounter":
            counter = int(value)
        elif operation == "addtocounter":
            counter += int(value)
        elif caption:
            counter += 1
            captions += 1
        else:
            assert label not in labels
            labels[label] = counter
    assert captions == 1
    assert labels == {"tab:runtime-identity-admission": preceding_tables + 1}
    assert counter == preceding_tables + 1
    # Automatic caption anchors must remain active; suppression is not a fix.
    assert not re.search(
        r"\\(?:renewcommand|providecommand|def)\s*\{?\\(?:thetable|theHtable)|"
        r"\\(?:captionsetup|hypersetup)\s*\{",
        fragment,
    )


@pytest.mark.parametrize("origin", ("generated", "persisted"))
def test_audit_publication_manifest_binds_bilingual_layouts_to_frozen_evidence(origin):
    from scripts import update_visual_source_manifest as publication

    manifest = (
        publication.build_manifest()
        if origin == "generated"
        else _load(ROOT / "visuals/source-manifest.json")
    )
    layouts = [
        f"paper/latex/generated/review_boundary_audit_{language}.tex" for language in LANGUAGES
    ]
    owners = [
        entry
        for entry in manifest["table_sources"]
        if any(receipt["path"] in layouts for receipt in entry["layout_sources"])
    ]
    assert len(owners) == 1, "Both audit layouts need one curated provenance registry entry"
    entry = owners[0]
    assert entry["kind"] == "table"
    assert Counter(entry["rendered_in"]) == Counter(("paper-en", "paper-ko"))
    assert Counter(entry["anchors"]) == Counter(AUDIT_TABLE_LABELS)

    def verify_receipts(receipts, paths):
        assert Counter(receipt["path"] for receipt in receipts) == Counter(paths)
        for receipt in receipts:
            payload = (ROOT / receipt["path"]).read_bytes()
            assert receipt["bytes"] == len(payload), receipt["path"]
            assert receipt["sha256"] == _digest(payload), receipt["path"]

    verify_receipts(entry["layout_sources"], layouts)
    verify_receipts([entry["generator"]], [publication.PAPER_TABLE_GENERATOR])
    data = [
        str(AUDIT / "results-v2" / name)
        for name in (
            "review_boundary_audit_en.tex",
            "review_boundary_audit_ko.tex",
            "summary.json",
            "rows.jsonl",
            "surface_rows.jsonl",
            "assignment_inventory.json",
            "input_hashes.json",
            "source_hashes.json",
            "protocol.json",
        )
    ]
    data.extend(
        str(AUDIT / name)
        for name in ("reviewer-source.public.json", "public-source-projection-v1.json")
    )
    verify_receipts(entry["data_sources"], data)
    surfaces = [
        surface
        for surface in manifest["rendered_surfaces"]
        if surface["id"] in entry["rendered_in"]
    ]
    assert Counter(surface["id"] for surface in surfaces) == Counter(entry["rendered_in"])
    for surface in surfaces:
        language = surface["id"].removeprefix("paper-")
        verify_receipts([surface["editable_source"]], [f"paper/latex/{language}/main.tex"])
        verify_receipts([surface["artifact"]], [f"paper/latex/{language}/main.pdf"])


@pytest.mark.parametrize("language", LANGUAGES)
@pytest.mark.parametrize("label", AUDIT_TABLE_LABELS)
def test_audit_table_typography_uses_booktabs_and_explicit_row_spacing(language, label):
    text = (GENERATED / f"review_boundary_audit_{language}.tex").read_text(encoding="utf-8")
    blocks = [
        table
        for table in re.findall(r"\\begin\{table\*\}\[t\](.*?)\\end\{table\*\}", text, re.DOTALL)
        if f"\\label{{{label}}}" in table
    ]
    assert len(blocks) == 1
    table = blocks[0]
    spacing = "\\renewcommand{\\arraystretch}{1.20}\n"
    assert table.count(spacing) == 1, "Each published audit table must set its own row spacing"
    assert "\\scriptsize\n" + spacing + "\\begin{tabular}" in table
    assert r"\hline" not in table
    tabular = re.search(r"\\begin\{tabular\}\{[^{}]+\}\n(.*?)\\end\{tabular\}", table, re.DOTALL)
    assert tabular is not None
    lines = tabular.group(1).splitlines()
    rules = [line for line in lines if line in (r"\toprule", r"\midrule", r"\bottomrule")]
    assert rules == [r"\toprule", r"\midrule", r"\bottomrule"]
    assert lines[0] == r"\toprule"
    assert lines[2] == r"\midrule", "The header must be separated from data rows"
    assert lines[-1] == r"\bottomrule"
